import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;

@PluginDescriptor(
    name = "Rival Radars",
    description = "Compares XP gains with rivals using TWOM and TempleOSRS APIs",
    tags = {"xp", "rival", "gmfinancial"}
)
public class RivalRadarPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private RivalRadarConfig config;
    @Inject private OverlayManager overlayManager;
    @Inject private OverlayManager overlayManager2;
    @Inject private Notifier notifier;

    private Map<String, Double> rivalXP = new HashMap<>();
    private Instant lastUpdate = Instant.now();

    @Override
    protected void startUp()
    {
        if (config.showOverlay())
        {
            overlayManager.add(new RivalRadarOverlay(overlayManager2));
        }
        updateRivals();
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(new RivalRadarOverlay(overlayManager2));
    }

    @Subscribe
    public void onGetPlayerStats(PlayerStatsChanged event)
    {
        if (!event.isLocalPlayer())
            return;

        for (Player player : event.getTargetPlayers())
        {
            double totalXP = 0;
            for (String skill : event.getSkills())
            {
                if (skill.equals("total")) continue;
                totalXP += event.getSkillXP(skill);
            )
            rivalXP.put(event.getTargetPlayer().getName(), totalXP);
        }
    }

    @Subscribe
    public void onScreenScrolled(ScreenScrolled event)
    {
        if (config.autoRefresh())
            updateRivals();
    }

    private void updateRivals()
    {
        Instant now = Instant.now();
        if (ChronoUnit.SECONDS.between(lastUpdate, now) < config.refreshInterval())
            return;

        lastUpdate = now;

        for (Map.Entry<String, Double> entry : rivalXP.entrySet())
        {
            String name = entry.getKey();
            double rivalXP = entry.getValue();
            double difference = rivalXP - calculateXP()

            if (Math.abs(difference) > config.threshold())
            {
                String notification = "Rival " + name + " has " + (difference > 0 ? "gained" : "lost") + " " + Math.round(Math.abs(difference)) + " XP!";
                notifier.notify(notification);
            }
        }
    }

    private double calculateXP()
    {
        double tpXP = calculateTWOMXP();
        double tempXP = calculateTempleOSRSXP();
        return (tpXP + tempXP) / 2;
    }

    private double calculateTWOMXP()
    {
        // Implementation using TWOM API
    }

    private double calculateTempleOSRSXP()
    {
        // Implementation using TempleOSRS API
    }
}

class RivalRadarConfig
{
    boolean showOverlay = true;
    boolean autoRefresh = true;
    int refreshInterval = 60; // seconds
    int threshold = 100;

    @Provides
    RivalRadarConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(RivalRadarConfig.class);
    }
